Below is a complete MATLAB/YALMIP script that synthesizes an H2 state-feedback controller using the Schur complement with Y = KX, and then compares its step responses against an LQR controller for both the plant output y and the control input u. The disturbance w is modeled as entering through the same channel as the control input (B). The plots show step responses from w (first channel) to y and to u.

```python
% H2 state-feedback with YALMIP (Schur complement) and step comparisons vs LQR
clc
clear
close all

% Load data and identify model (user-supplied data3 must exist)
load('data3.mat');                          % expects variable data3
G3  = bj(data3, [5 5 5 5 1]);               % Box-Jenkins identification (SISO typical)
G3c = d2c(G3);                              % Discrete -> continuous
sysc = ss(G3c);                             % Convert to state-space
[A,B,C,D] = ssdata(sysc);
n = size(A,1);
m = size(B,2);
p = size(C,1);

% Generalized plant for H2:
% xdot = A x + B (w + u),   u = -K x
% z    = [C x; -K x] = C1 x + D12 u,  with Y = KX
C1  = [C; zeros(m,n)];                      % For z = C1 x + D12 u
D12 = [zeros(p,m); eye(m)];

% YALMIP decision variables
X = sdpvar(n,n,'symmetric');                % X > 0
Y = sdpvar(m,n,'full');                     % Y = K X
Z = sdpvar(p+m,p+m,'symmetric');            % For H2 objective

% LMIs:
% 1) Closed-loop Lyapunov with disturbance at same input B:
%    A X + X A' - (B Y + Y' B') + B B' < 0
eps_stab = 1e-9;
LMI_cl = A*X + X*A' - (B*Y + Y'*B') + (B*B') <= -eps_stab*eye(n);

% 2) H2 objective (z = C1 x + D12 u, u = -K x, Y = KX) via Schur complement:
%    [ Z,  (C1 X - D12 Y)
%      *,               X ] >= 0
LMI_h2 = [ Z,              (C1*X - D12*Y) ; ...
           (C1*X - D12*Y)',             X ] >= 0;

% Positive definiteness
LMI_pos = X >= 1e-6*eye(n);

Constraints = [LMI_cl, LMI_h2, LMI_pos];

% Objective: minimize trace(Z) = ||T_{w->z}||_2^2
Objective = trace(Z);

% Select solver (MOSEK preferred; fallback to SeDuMi if not found)
if exist('mosekopt','file') == 3 || exist('mosekopt','file') == 2
    solver = 'mosek';
else
    solver = 'sedumi';
end
ops = sdpsettings('solver',solver,'verbose',1);

% Solve the SDP
sol = optimize(Constraints, Objective, ops);
assert(sol.problem == 0, ['SDP failed: ', sol.info]);

% Recover controller K and H2 norm
Xv = value(X);
Yv = value(Y);
Kv = Yv / Xv;                               % K = Y * X^{-1}
H2sq = value(trace(Z));                     % squared H2 norm from w to z
H2norm = sqrt(max(H2sq,0));

fprintf('Controller synthesis successful.\n');
fprintf('||T_{w->z}||_2 = %.6f\n', H2norm);

% Closed-loop systems (from disturbance w to outputs)
Acl = A - B*Kv;
Bcl = B;
Cy  = C;                                    % output y
Dyw = zeros(p, m);

% Output y to w
sys_y_H2  = ss(Acl, Bcl, Cy,  Dyw);

% Control input u = -K x (as an output) to w
Cu  = -Kv;
Duw = zeros(m, m);
sys_u_H2  = ss(Acl, Bcl, Cu,  Duw);

% LQR comparison
Q = eye(n);
R = 1;
K_lqr = lqr(A,B,Q,R);

Acl_lqr = A - B*K_lqr;
sys_y_LQR = ss(Acl_lqr, Bcl, Cy,  Dyw);
sys_u_LQR = ss(Acl_lqr, Bcl, -K_lqr, Duw);

% Step response comparisons (disturbance step at w, first input channel)
tFinal = 5;                                 % seconds; adjust if needed
t = linspace(0,tFinal,1000).';

inp = 1;                                    % compare for first disturbance channel

% y response: from w(inp) to each output y(i)
[Y_H2, ty]  = step(sys_y_H2(:,inp), t);
[Y_LQR, ~]  = step(sys_y_LQR(:,inp), t);

% Ensure 2D matrices (length(t) x p)
if ndims(Y_H2) == 3, Y_H2 = squeeze(Y_H2); end
if ndims(Y_LQR) == 3, Y_LQR = squeeze(Y_LQR); end

for i = 1:p
    figure
    plot(ty, Y_H2(:,i), 'b-', 'LineWidth', 1.5); hold on
    plot(ty, Y_LQR(:,i), 'r--', 'LineWidth', 1.5); grid on
    xlabel('Time [s]'); ylabel(sprintf('y(%d)', i));
    title(sprintf('Step: w(%d) -> y(%d)', inp, i));
    legend('H2', 'LQR', 'Location', 'Best');
end

% u response: from w(inp) to each control input u(j)
[U_H2, tu]  = step(sys_u_H2(:,inp), t);
[U_LQR, ~]  = step(sys_u_LQR(:,inp), t);

if ndims(U_H2) == 3, U_H2 = squeeze(U_H2); end
if ndims(U_LQR) == 3, U_LQR = squeeze(U_LQR); end

for j = 1:m
    figure
    plot(tu, U_H2(:,j), 'b-', 'LineWidth', 1.5); hold on
    plot(tu, U_LQR(:,j), 'r--', 'LineWidth', 1.5); grid on
    xlabel('Time [s]'); ylabel(sprintf('u(%d)', j));
    title(sprintf('Step: w(%d) -> u(%d)', inp, j));
    legend('H2', 'LQR', 'Location', 'Best');
end

% Optional: print eigenvalues to confirm closed-loop stability
fprintf('Closed-loop poles (H2):\n'); disp(eig(Acl).');
fprintf('Closed-loop poles (LQR):\n'); disp(eig(Acl_lqr).');
``` 

Notes:
- The H2 design minimizes the sum of the squared H2 norms from the disturbance w to the output y and to the control input u by embedding z = [y; u] with Y = KX.
- For multi-input systems, the figures compare responses for the first disturbance channel (inp = 1). Adjust inp or loop over inputs if needed.
- If MOSEK is installed, it will be used; otherwise SeDuMi is used as fallback.

Here is the key idea and how it resolves the nonlinearity so the problem can be parsed as LMIs by YALMIP:

- Where the nonlinearity comes from:
  - The closed-loop matrix is Acl = A − B K, so stability with a Lyapunov variable X introduces the bilinear term K X (or X K') when you write Acl X + X Acl' + B B' < 0.
  - The H2 performance also depends on K in z = [y1; y2] = [C x; −K x] = C1 x + D12 u with u = −K x. The squared H2 norm is trace((C1 − D12 K) X (C1 − D12 K)') which again contains the bilinear product K X and an inverse if you try to express it via Gramians.

- How Schur complement linearizes it:
  - Introduce the standard change of variables Y = K X. This removes the bilinear term K X from the stability inequality:
    Acl X + X Acl' + B B' < 0  becomes  A X + X A' − (B Y + Y' B') + B B' < 0, which is linear in (X, Y).
  - The H2 objective involves (C1 − D12 K) X (C1 − D12 K)'. Using Y = K X, this becomes (C1 X − D12 Y) X^{-1} (C1 X − D12 Y)'. The Schur complement enforces Z ≥ (C1 X − D12 Y) X^{-1} (C1 X − D12 Y)' via the LMI:
    [ Z,  C1 X − D12 Y; (C1 X − D12 Y)',  X ] ≥ 0.
    Minimizing trace(Z) then minimizes an upper bound that is tight at the optimum, yielding the squared H2 norm ||T_{w→z}||_2^2, with z = [y; u]. This is precisely the sum of the squared H2 norms from the disturbance to the plant output and to the control input.

- Relation to the bounded real lemma (BRL):
  - The BRL provides LMI conditions for an H∞ bound on the L2 gain. While our objective is H2 (not H∞), the same “completion of squares” and Schur complement machinery underlies both formulations. The closed-loop Lyapunov inequality guaranteeing internal stability with input disturbance is analogous to the BRL feasibility part; the H2-specific part replaces the H∞ bound with the trace objective enforced through the Schur complement to avoid X^{-1}.

