import sys
from collections import Counter

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    i = 0
    if i >= len(data):
        print(0)
        return

    n = data[i]; i += 1
    a = data[i:i+n]; i += n

    if i >= len(data):
        print(0)
        return

    m = data[i]; i += 1
    b = data[i:i+m]; i += m

    ca = Counter(a)
    cb = Counter(b)

    # Size of multiset intersection
    if len(ca) > len(cb):
        ca, cb = cb, ca
    ans = sum(min(cnt, cb[x]) for x, cnt in ca.items() if x in cb)
    print(ans)

if __name__ == "__main__":
    main()
