# Part 2: Similarity-based comparison/deletion (perceptual hashing)
# ---------------------------------------------------------
@dataclass(frozen=True)
class _ImgInfo:
    path: Path
    width: int
    height: int
    file_size: int
    mtime: float
    phash: Any  # imagehash.ImageHash
    bits: int   # total number of bits in the hash


def _make_hash_func(name: str, hash_size: int):
    """
    Returns a callable that computes a perceptual hash using the chosen algorithm and hash_size.
    """
    if imagehash is None:
        raise RuntimeError("imagehash is not installed. Install with: pip install imagehash")

    name = (name or "phash").lower()
    mapping = {
        "ahash": imagehash.average_hash,
        "phash": imagehash.phash,
        "dhash": imagehash.dhash,
        "whash": imagehash.whash,
    }
    if name not in mapping:
        raise ValueError(f"Unsupported hash_algorithm '{name}'. Choose from: {', '.join(mapping.keys())}")

    # imagehash functions accept hash_size (whash also accepts it for default Haar mode)
    return partial(mapping[name], hash_size=hash_size)


def _compute_hash(
    fpath: Path,
    hash_func,
    *,
    exif_transpose: bool = True,
) -> Optional[_ImgInfo]:
    try:
        with Image.open(fpath) as im:
            if exif_transpose:
                try:
                    im = ImageOps.exif_transpose(im)
                except Exception:
                    pass
            h = hash_func(im)  # imagehash.ImageHash
            width, height = im.size
    except (UnidentifiedImageError, OSError):
        return None
    except Exception:
        # Bubble up unexpected errors to be counted by caller
        raise

    try:
        stat = fpath.stat()
        fsize = stat.st_size
        mtime = stat.st_mtime
    except Exception:
        fsize = -1
        mtime = 0.0

    # imagehash.ImageHash.hash is an NxN numpy bool array; bits = N*N
    bits = int(h.hash.size) if hasattr(h, "hash") else 64  # sensible default fallback

    return _ImgInfo(
        path=fpath,
        width=int(width),
        height=int(height),
        file_size=int(fsize),
        mtime=float(mtime),
        phash=h,
        bits=bits,
    )


def _choose_keep(candidates: List[_ImgInfo], policy: str) -> _ImgInfo:
    policy = (policy or "largest").lower()

    if policy == "largest":
        key = lambda x: (x.width * x.height, x.file_size, x.mtime, str(x.path))
        return max(candidates, key=key)
    if policy == "smallest":
        key = lambda x: (-(x.width * x.height), -x.file_size, -x.mtime, str(x.path))
        return max(candidates, key=key)
    if policy == "newest":
        key = lambda x: (x.mtime, x.width * x.height, x.file_size, str(x.path))
        return max(candidates, key=key)
    if policy == "oldest":
        key = lambda x: (-x.mtime, x.width * x.height, x.file_size, str(x.path))
        return max(candidates, key=key)
    if policy == "largest_filesize":
        key = lambda x: (x.file_size, x.width * x.height, x.mtime, str(x.path))
        return max(candidates, key=key)
    if policy == "first":
        # Deterministic by path
        key = lambda x: (0, 0, 0, str(x.path))
        return min(candidates, key=key)

    raise ValueError("Unsupported keep policy. Choose one of: largest, smallest, newest, oldest, largest_filesize, first")


def _hamming_distance(a: _ImgInfo, b: _ImgInfo) -> int:
    # imagehash supports subtraction resulting in Hamming distance
    return int(a.phash - b.phash)


def _similarity_ratio(a: _ImgInfo, b: _ImgInfo) -> float:
    # Similarity in [0, 1], where 1.0 means identical hashes
    dist = _hamming_distance(a, b)
    bits = max(1, min(a.bits, b.bits))
    return 1.0 - (dist / bits)


def _group_similar(
    infos: List[_ImgInfo],
    *,
    max_distance: Optional[int],
    similarity_threshold: Optional[float],
) -> List[List[_ImgInfo]]:
    """
    Greedy grouping: pick an unassigned image as a seed, put all other unassigned images
    that meet the threshold with it into the same group. O(n^2) worst-case.
    """
    if not infos:
        return []

    bits = infos[0].bits
