        # Convert threshold in [0,1] to Hamming distance (lower is more similar)
        # Distance allowed is the number of differing bits.
        calc_max_distance = max(0, min(bits, floor((1.0 - similarity_threshold) * bits)))
    else:
        calc_max_distance = None

    if max_distance is None and calc_max_distance is None:
        # default: consider "very similar" as >= 0.95 similarity
        calc_max_distance = max(0, floor(0.05 * bits))

    if max_distance is not None:
        # If provided explicitly, use it
        calc_max_distance = int(max(0, min(bits, max_distance)))

    groups: List[List[_ImgInfo]] = []
    assigned: Set[Path] = set()

    # Sort to keep behavior stable across runs
    infos_sorted = sorted(infos, key=lambda x: (str(x.path)))

    for i, seed in enumerate(infos_sorted):
        if seed.path in assigned:
            continue
        group = [seed]
        assigned.add(seed.path)
        for j in range(i + 1, len(infos_sorted)):
            other = infos_sorted[j]
            if other.path in assigned:
                continue
            d = _hamming_distance(seed, other)
            if d <= calc_max_distance:
                group.append(other)
                assigned.add(other.path)
        groups.append(group)

    return groups


