Below is a small, reusable Flutter/Dart utility that slices an image into four quadrants from the center. It returns each quadrant as PNG bytes (Uint8List), which you can display using Image.memory or save to files.

```python
// Dart/Flutter code

import 'dart:typed_data';
import 'dart:ui' as ui;
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

/// Slices an image (provided as raw bytes) into four quadrants from the center.
/// Returns four PNG byte arrays in order: topLeft, topRight, bottomLeft, bottomRight.
Future<List<Uint8List>> sliceImageIntoFour(Uint8List imageBytes) async {
  final codec = await ui.instantiateImageCodec(imageBytes);
  final frame = await codec.getNextFrame();
  final image = frame.image;
  return _sliceUiImageIntoFour(image);
}

/// Internal: slices a ui.Image into four quadrants.
Future<List<Uint8List>> _sliceUiImageIntoFour(ui.Image image) async {
  final w = image.width;
  final h = image.height;

  // Midpoints, integer-safe (odd sizes give extra pixel to right/bottom)
  final midW = w ~/ 2;
  final midH = h ~/ 2;

  final rects = <ui.Rect>[
    // Top-left
    ui.Rect.fromLTWH(0, 0, midW.toDouble(), midH.toDouble()),
    // Top-right
    ui.Rect.fromLTWH(midW.toDouble(), 0, (w - midW).toDouble(), midH.toDouble()),
    // Bottom-left
    ui.Rect.fromLTWH(0, midH.toDouble(), midW.toDouble(), (h - midH).toDouble()),
    // Bottom-right
    ui.Rect.fromLTWH(midW.toDouble(), midH.toDouble(), (w - midW).toDouble(), (h - midH).toDouble()),
  ];

  final parts = <Uint8List>[];
  for (final r in rects) {
    parts.add(await _cropToPngBytes(image, r));
  }
  return parts;
}

/// Crops a ui.Image by [srcRect] and returns PNG bytes.
Future<Uint8List> _cropToPngBytes(ui.Image src, ui.Rect srcRect) async {
  final recorder = ui.PictureRecorder();
  final canvas = ui.Canvas(recorder);
  final paint = ui.Paint();

  // Draw the specified source rectangle into a new image sized to that rect
  final dstRect = ui.Rect.fromLTWH(0, 0, srcRect.width, srcRect.height);
  canvas.drawImageRect(src, srcRect, dstRect, paint);

  final picture = recorder.endRecording();
  final cropped = await picture.toImage(
    srcRect.width.toInt(),
    srcRect.height.toInt(),
  );

  final byteData = await cropped.toByteData(format: ui.ImageByteFormat.png);
  // If you are on a recent Flutter version, you can free memory:
  // cropped.dispose();

  return byteData!.buffer.asUint8List();
}


