// Dart/Flutter code with added error handling

import 'dart:typed_data';
import 'dart:ui' as ui;
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

/// Domain-specific exceptions to make error handling clearer to callers.
class ImageSlicingException implements Exception {
  final String message;
  ImageSlicingException(this.message);
  @override
  String toString() => 'ImageSlicingException: $message';
}

class InvalidImageDataException extends ImageSlicingException {
  InvalidImageDataException(String message) : super(message);
}

class UnsupportedImageFormatException extends ImageSlicingException {
  UnsupportedImageFormatException(String message) : super(message);
}

/// Slices an image (provided as raw bytes) into four quadrants from the center.
/// Returns four PNG byte arrays in order: topLeft, topRight, bottomLeft, bottomRight.
///
/// Error handling:
/// - Throws InvalidImageDataException if bytes are null/empty or cannot be decoded.
/// - Throws UnsupportedImageFormatException if the format is not supported on the platform.
/// - Throws ImageSlicingException if the image is too small to slice (must be at least 2x2 px).
Future<List<Uint8List>> sliceImageIntoFour(Uint8List? imageBytes) async {
  // Basic validation
  if (imageBytes == null) {
    throw InvalidImageDataException('imageBytes is null. Provide valid image bytes.');
  }
  if (imageBytes.isEmpty) {
    throw InvalidImageDataException('imageBytes is empty. Provide non-empty image data.');
  }

  ui.Codec codec;

  // Robust decoding with granular error messages
  try {
    codec = await ui.instantiateImageCodec(imageBytes);
  } on UnsupportedError catch (e) {
    // Some platforms may not support certain formats.
    throw UnsupportedImageFormatException(
      'Unsupported image format on this platform. Details: ${e.message ?? e.toString()}',
    );
  } on ArgumentError catch (e) {
    // Common for invalid/corrupted data
    throw InvalidImageDataException('Invalid or corrupted image data. ${e.message ?? e.toString()}');
  } on Exception catch (e) {
    // Fallback for other decode-time issues (e.g., codec backend failures)
    final msg = e.toString();
    if (msg.contains('Invalid image') || msg.contains('bad image data')) {
      throw InvalidImageDataException('Invalid or corrupted image data.');
    }
    throw ImageSlicingException('Failed to decode image: $e');
  }

  final frame = await codec.getNextFrame();
  final image = frame.image;

  return _sliceUiImageIntoFour(image);
}

/// Internal: slices a ui.Image into four quadrants.
Future<List<Uint8List>> _sliceUiImageIntoFour(ui.Image image) async {
  final w = image.width;
  final h = image.height;

  // Guard: cannot slice if either dimension is < 2, as one or more quadrants would be 0-sized.
  if (w < 2 || h < 2) {
    throw ImageSlicingException('Image must be at least 2x2 pixels to slice into four quadrants.');
  }

  // Midpoints, integer-safe (odd sizes give extra pixel to right/bottom)
  final midW = w ~/ 2;
  final midH = h ~/ 2;

  final rects = <ui.Rect>[
    // Top-left
    ui.Rect.fromLTWH(0, 0, midW.toDouble(), midH.toDouble()),
    // Top-right
    ui.Rect.fromLTWH(midW.toDouble(), 0, (w - midW).toDouble(), midH.toDouble()),
    // Bottom-left
    ui.Rect.fromLTWH(0, midH.toDouble(), midW.toDouble(), (h - midH).toDouble()),
    // Bottom-right
    ui.Rect.fromLTWH(midW.toDouble(), midH.toDouble(), (w - midW).toDouble(), (h - midH).toDouble()),
  ];

  final parts = <Uint8List>[];
  for (final r in rects) {
    // Extra safety: ensure no zero-sized rects slip through.
    if (r.width <= 0 || r.height <= 0) {
      throw ImageSlicingException(
        'Encountered a zero-sized quadrant (${r.width}x${r.height}). '
        'Source image might be too small.',
      );
    }
    parts.add(await _cropToPngBytes(image, r));
  }
  return parts;
}

/// Crops a ui.Image by [srcRect] and returns PNG bytes.
Future<Uint8List> _cropToPngBytes(ui.Image src, ui.Rect srcRect) async {
  final recorder = ui.PictureRecorder();
  final canvas = ui.Canvas(recorder);
  final paint = ui.Paint();

  // Draw the specified source rectangle into a new image sized to that rect
  final dstRect = ui.Rect.fromLTWH(0, 0, srcRect.width, srcRect.height);
  canvas.drawImageRect(src, srcRect, dstRect, paint);

  final picture = recorder.endRecording();

  ui.Image cropped;
  try {
    cropped = await picture.toImage(
      srcRect.width.toInt(),
      srcRect.height.toInt(),
    );
  } on Exception catch (e) {
    throw ImageSlicingException('Failed to crop image: $e');
  }

  final byteData = await cropped.toByteData(format: ui.ImageByteFormat.png);
  if (byteData == null) {
    throw ImageSlicingException('Failed to encode cropped image to PNG bytes.');
  }

  // Optionally free memory on newer Flutter versions:
  // cropped.dispose();

  return byteData.buffer.asUint8List();
}

