    if (!root) return new Node(key);
    Node* cur = root;
    while (true) {
        if (key < cur->key) {
            if (cur->left) {
                cur = cur->left;
            } else {
                cur->left = new Node(key);
                break;
            }
        } else {
            if (cur->right) {
                cur = cur->right;
            } else {
                cur->right = new Node(key);
                break;
            }
        }
    }
    return root;
}

