function [x,err,fig] = solve_LS(A, b)
% Solve Ax ≈ b. If A is square and full rank, solve exactly; otherwise use least squares.
% Then compute residuals err = Ax - b and plot them as specified.

    % Ensure b is a column vector
    b = b(:);

    % Basic size checks
    [m,n] = size(A);
    if length(b) ~= m
        error('Length of b (%d) must match number of rows of A (%d).', length(b), m);
    end

    % Rank check
    r = rank(A);

    % Solve system:
    % - Exact solve when A is square and full rank
    % - Otherwise, least squares (MATLAB backslash does LS automatically)
    if m == n && r == n
        x = A \ b;
    else
        x = A \ b;   % least-squares solution
    end

    % Residuals (error per equation)
    err = A*x - b;
    % Optional overall fit error (2-norm). Not required to return.
    % c_star = norm(err, 2);

    % Prepare x-values for plotting the residual at each observation
    if n == 1
        x_plot = A(:,1);           % use the single predictor values on x-axis
    else
        x_plot = (1:m).';          % otherwise use observation indices
    end

    % Create figure and plot
    fig = figure; hold on;

    % Black points for each residual, MarkerSize = 20
    plot(x_plot, err, 'k.', 'MarkerSize', 20);

    % Red dotted horizontal line at y = 0
    yline(0, 'r:', 'LineWidth', 2);

    % Blue dotted lines from each point down/up to y = 0
    for i = 1:m
        line([x_plot(i) x_plot(i)], [0 err(i)], 'Color', 'b', 'LineStyle', ':', 'LineWidth', 1.5);
    end

    % Axis limits with padding of 1 on both x and y
    xmin = min(x_plot); xmax = max(x_plot);
    ymin = min(err);    ymax = max(err);
    xlim([xmin - 1, xmax + 1]);
    ylim([ymin - 1, ymax + 1]);

    % Labels and title
    xlabel('x');
    ylabel('Ax-b');
    title('Error computed from Ax-b');

    grid on; box on;
end
