// C#
// A utility method that takes a System.Drawing.Image and returns a byte[],
// with optional downscaling and quality control. Supports JPEG and PNG.
//
// Notes:
// - JPEG: lossy; "quality" (0-100) is honored via encoder parameters.
// - PNG: lossless; quality is not meaningful in System.Drawing. Size can be reduced
//        by resizing and by using an opaque 24bpp pixel format when no alpha is needed.
// - On non-Windows platforms, System.Drawing.Common has limitations. Consider libraries
//   like SixLabors.ImageSharp or SkiaSharp for cross-platform production use.

using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;

public static class ImageBytes
{
    // image: source image
    // outputFormat: "jpeg" (or "jpg") or "png"
    // quality: 0-100 (for JPEG; ignored by PNG)
    // maxWidth, maxHeight: optional bounding box for resizing; null keeps original
    // preserveAspectRatio: fit within the box maintaining aspect ratio
    // allowUpscale: if false, image won't be enlarged beyond original size
    public static byte[] ToByteArray(
        Image image,
        string outputFormat = "jpeg",
        int quality = 85,
        int? maxWidth = null,
        int? maxHeight = null,
        bool preserveAspectRatio = true,
        bool allowUpscale = false)
    {
        if (image == null) throw new ArgumentNullException(nameof(image));
        if (string.IsNullOrWhiteSpace(outputFormat)) throw new ArgumentNullException(nameof(outputFormat));

        string fmt = outputFormat.Trim().ToLowerInvariant();
        bool isJpeg = fmt == "jpeg" || fmt == "jpg";
        bool isPng  = fmt == "png";
        if (!isJpeg && !isPng)
            throw new ArgumentException("outputFormat must be 'jpeg'/'jpg' or 'png'.");

        // Determine target size
        Size srcSize = image.Size;
        Size targetSize = ComputeTargetSize(srcSize, maxWidth, maxHeight, preserveAspectRatio, allowUpscale);

        // Choose target pixel format
        // - JPEG does not support alpha; use 24bpp RGB.
        // - PNG: keep alpha when present; otherwise 24bpp RGB for smaller files.
        PixelFormat targetPixelFormat;
        if (isJpeg)
        {
            targetPixelFormat = PixelFormat.Format24bppRgb;
        }
        else
        {
            bool srcHasAlpha = Image.IsAlphaPixelFormat(image.PixelFormat);
            targetPixelFormat = srcHasAlpha ? PixelFormat.Format32bppArgb : PixelFormat.Format24bppRgb;
        }

        using var processed = Render(image, targetSize, targetPixelFormat);

        using var ms = new MemoryStream();

        if (isJpeg)
        {
            // Clamp quality to [0,100]
            long q = Math.Min(100, Math.Max(0, quality));
            var jpegCodec = GetEncoder("image/jpeg") ?? throw new InvalidOperationException("JPEG encoder not found.");
            using var encParams = new EncoderParameters(1);
            encParams.Param[0] = new EncoderParameter(Encoder.Quality, q);
            processed.Save(ms, jpegCodec, encParams);
        }
        else // PNG
        {
            // System.Drawing does not expose a quality/compression level for PNG.
            // We rely on:
            // - resizing (done above)
            // - dropping alpha when not needed (using 24bpp above)
            processed.Save(ms, ImageFormat.Png);
        }

        return ms.ToArray();
    }

    private static Size ComputeTargetSize(
        Size original,
        int? maxWidth,
        int? maxHeight,
        bool preserveAspect,
        bool allowUpscale)
    {
        if (maxWidth == null && maxHeight == null)
            return original;

        int boxW = maxWidth  ?? int.MaxValue;
        int boxH = maxHeight ?? int.MaxValue;

        if (preserveAspect)
        {
            double scaleW = (double)boxW / original.Width;
            double scaleH = (double)boxH / original.Height;
            double scale = Math.Min(scaleW, scaleH);

            if (!allowUpscale)
                scale = Math.Min(1.0, scale);

            int w = Math.Max(1, (int)Math.Round(original.Width * scale));
            int h = Math.Max(1, (int)Math.Round(original.Height * scale));
            return new Size(w, h);
        }
        else
        {
            int w = maxWidth  ?? original.Width;
            int h = maxHeight ?? original.Height;

            if (!allowUpscale)
            {
                w = Math.Min(w, original.Width);
                h = Math.Min(h, original.Height);
            }

            w = Math.Max(1, w);
            h = Math.Max(1, h);
            return new Size(w, h);
        }
    }

    // Downscale/draw to a new bitmap with the requested pixel format.
    private static Bitmap Render(Image src, Size targetSize, PixelFormat pixelFormat)
    {
        var bmp = new Bitmap(targetSize.Width, targetSize.Height, pixelFormat);

        using (var g = Graphics.FromImage(bmp))
        {
            // Preserve alpha correctness when drawing onto ARGB
            if (pixelFormat == PixelFormat.Format32bppArgb || pixelFormat == PixelFormat.Format32bppPArgb)
                g.CompositingMode = CompositingMode.SourceCopy;

            g.SmoothingMode = SmoothingMode.HighQuality;
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.CompositingQuality = CompositingQuality.HighQuality;

Below are practical ways to control PNG size and “quality” in C#, plus code you can drop into your project. For PNG, “quality” typically means one or more of:
- Resizing (fewer pixels).
- Reducing color depth (palette/quantization to ≤256 colors).
- Removing alpha when not needed.
- Increasing DEFLATE compression effort (zlib level).
- Choosing PNG filter strategy.
- Stripping metadata (EXIF/ICC/XMP).

1) SixLabors.ImageSharp (pure managed, cross-platform)
- Controls: resize, quantize to palette (up to 256 colors), drop alpha, compression level, filter, strip metadata.
- NuGet: SixLabors.ImageSharp

```python
// C# (ImageSharp)
// <PackageReference Include="SixLabors.ImageSharp" Version="3.*" />

using System;
using System.IO;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.PixelFormats;
using SixLabors.ImageSharp.Formats.Png;
using SixLabors.ImageSharp.Processing;

public static class PngTools_ImageSharp
{
    // input: byte[] or Stream
    public static byte[] EncodePng_ImageSharp(
        Stream input,
        int? maxWidth = null,
        int? maxHeight = null,
        bool preserveAspect = true,
        bool dropAlpha = false,         // flatten to opaque
        bool usePalette = true,         // quantize to ≤256 colors
        int paletteColors = 256,        // 2..256
        int compressionLevel = 9        // 0..9 (higher = smaller/slower)
    )
    {
        using var image = Image.Load<Rgba32>(input);

        // Resize if requested
        if (maxWidth.HasValue || maxHeight.HasValue)
        {
            var size = ComputeTargetSize(image.Width, image.Height, maxWidth, maxHeight, preserveAspect);
            image.Mutate(x => x.Resize(size.width, size.height));
        }

        // Optionally drop alpha (if you can render on a background color, do it here)
        if (dropAlpha)
        {
            image.Mutate(x => x.BackgroundColor(SixLabors.ImageSharp.Color.White));
        }

        // Prepare encoder
        var encoder = new PngEncoder
        {
            CompressionLevel = (PngCompressionLevel)Math.Clamp(compressionLevel, 0, 9), // Level0..Level9
            FilterMethod = PngFilterMethod.Adaptive,
            InterlaceMethod = PngInterlaceMode.None,
            IgnoreMetadata = true
        };

        // If you can use a palette (PNG-8) this often gives the biggest savings
        if (usePalette)
        {
            // Keep to ≤256 colors; dithering may help gradients look better
            // KnownQuantizers.Wu is a solid general-purpose quantizer
            encoder.ColorType = PngColorType.Palette;
            encoder.BitDepth = PngBitDepth.Bit8;
            encoder.Quantizer = KnownQuantizers.Wu(new QuantizerOptions
            {
                MaxColors = Math.Clamp(paletteColors, 2, 256),
                Dither = KnownDitherings.FloydSteinberg
            });
        }
        else
        {
            // Choose color type based on alpha drop
            encoder.ColorType = dropAlpha ? PngColorType.Rgb : PngColorType.Rgba;
            encoder.BitDepth = PngBitDepth.Bit8;
        }

        using var ms = new MemoryStream();
        image.SaveAsPng(ms, encoder);
        return ms.ToArray();
    }

    private static (int width, int height) ComputeTargetSize(
        int w, int h, int? maxW, int? maxH, bool preserveAspect)
    {
        if (!maxW.HasValue && !maxH.HasValue) return (w, h);
        int boxW = maxW ?? int.MaxValue;
        int boxH = maxH ?? int.MaxValue;
        if (preserveAspect)
