% Preallocate
d2y = zeros(size(y));

% Endpoints: 4-point one-sided, O(dx^2)
d2y(1) = ( 2*y(1) - 5*y(2) + 4*y(3) - y(4) ) / dx^2;
d2y(N) = ( 2*y(N) - 5*y(N-1) + 4*y(N-2) - y(N-3) ) / dx^2;

% Near-boundary: 3-point centered, O(dx^2)
d2y(2)   = ( y(3) - 2*y(2) + y(1) ) / dx^2;
d2y(N-1) = ( y(N) - 2*y(N-1) + y(N-2) ) / dx^2;

% Interior: 5-point centered, O(dx^4), valid for i = 3..N-2 (1-based)
for i = 3:N-2
    d2y(i) = ( -y(i+2) + 16*y(i+1) - 30*y(i) + 16*y(i-1) - y(i-2) ) / (12*dx^2);
end

% Optional: quick check
err = d2y - ypp_true;
fprintf('dx = %.3f, N = %d\n', dx, N);
fprintf('Max abs error: % .3e\n', max(abs(err)));

% Optional plot
