# Configuration
FOLDERS = ["Ewl.Platform.Analytics"]  # repositories to process, relative to where you run this script

FEATURE_BRANCH = "TK/14278_TM-13"
MAIN_REMOTE_BRANCH = "origin/main"
TARGET_LINE = "o.Select().Filter().OrderBy().Count().Expand().SetMaxTop(100);"
INSERT_LINE = "o.TimeZone = TimeZoneInfo.Utc;"  # will be inserted on a new line after TARGET_LINE

API_PACKAGE = ("Ewl.Platform.Common.Api", "1.0.0")
STORAGE_PACKAGE = ("Ewl.Platform.Common.Storage", "1.0.0")


def run(cmd: List[str], cwd: Optional[Path] = None, check: bool = True) -> subprocess.CompletedProcess:
    print(f"[RUN] {' '.join(cmd)} (cwd={cwd or Path.cwd()})")
    return subprocess.run(cmd, cwd=str(cwd) if cwd else None, check=check)


def safe_run(cmd: List[str], cwd: Optional[Path] = None) -> bool:
    try:
        res = run(cmd, cwd=cwd, check=False)
        return res.returncode == 0
    except Exception as e:
        print(f"[WARN] Failed to run {cmd}: {e}")
        return False


@contextmanager
def pushd(new_dir: Path):
    prev = Path.cwd()
    try:
        os.chdir(new_dir)
        yield
    finally:
        os.chdir(prev)


def is_git_repo(path: Path) -> bool:
    return (path / ".git").exists()


def ensure_on_main_at_origin(repo_dir: Path) -> None:
    run(["git", "fetch", "origin", "--prune"], cwd=repo_dir)
    # Force-create/reset local main to origin/main and check it out
    run(["git", "checkout", "-B", "main", MAIN_REMOTE_BRANCH], cwd=repo_dir)
    run(["git", "reset", "--hard", MAIN_REMOTE_BRANCH], cwd=repo_dir)


def ensure_feature_branch_from_origin_main(repo_dir: Path) -> None:
    exists = safe_run(["git", "rev-parse", "--verify", FEATURE_BRANCH], cwd=repo_dir)
    if exists:
        run(["git", "checkout", FEATURE_BRANCH], cwd=repo_dir)
        run(["git", "reset", "--hard", MAIN_REMOTE_BRANCH], cwd=repo_dir)
    else:
        run(["git", "checkout", "-b", FEATURE_BRANCH, MAIN_REMOTE_BRANCH], cwd=repo_dir)


def find_solution(repo_dir: Path) -> Optional[Path]:
    slns = list(repo_dir.glob("*.sln"))
    return slns[0] if slns else None


def find_cs_files(repo_dir: Path, filename: str) -> List[Path]:
    results = []
    for p in repo_dir.rglob(filename):
        # Skip common build folders
        parts_lower = [part.lower() for part in p.parts]
        if "bin" in parts_lower or "obj" in parts_lower or ".git" in parts_lower:
            continue
        results.append(p)
    return results


def insert_timezone_after_target_line(file_path: Path) -> bool:
    text = file_path.read_text(encoding="utf-8", errors="ignore")
    newline = "\r\n" if "\r\n" in text else "\n"

    lines = text.splitlines(keepends=True)
    modified = False

    i = 0
    while i < len(lines):
        if lines[i].strip() == TARGET_LINE:
            # If next non-empty line already equals INSERT_LINE, skip
            next_line = lines[i + 1].strip() if i + 1 < len(lines) else ""
            if next_line != INSERT_LINE:
                indent_match = re.match(r"\s*", lines[i])
                indent = indent_match.group(0) if indent_match else ""
                lines.insert(i + 1, f"{indent}{INSERT_LINE}{newline}")
                modified = True
                i += 1  # skip newly inserted
        i += 1

    if modified:
        file_path.write_text("".join(lines), encoding="utf-8")
        print(f"[INFO] Updated {file_path}")
    else:
        print(f"[INFO] No changes needed in {file_path}")

    return modified


def find_main_project_csproj(repo_dir: Path, folder_name: str) -> Optional[Path]:
    # Prefer src/<folder_name>/<folder_name>.csproj
    candidate_dir = repo_dir / "src" / folder_name
    if candidate_dir.exists():
        csprojs = list(candidate_dir.glob("*.csproj"))
        if csprojs:
            exact = [p for p in csprojs if p.stem == folder_name]
            return exact[0] if exact else csprojs[0]

    # Fallback: any csproj under src that matches folder name
    src_dir = repo_dir / "src"
    if not src_dir.exists():
        return None
    csprojs = list(src_dir.rglob("*.csproj"))
    exact = [p for p in csprojs if p.stem == folder_name]
    if exact:
        return exact[0]
    return csprojs[0] if csprojs else None


def find_storage_csprojs(repo_dir: Path) -> List[Path]:
    results = []
    src_dir = repo_dir / "src"
    if not src_dir.exists():
        return results
    for p in src_dir.rglob("*.csproj"):
        if p.name.lower().endswith(".storage.csproj"):
            results.append(p)
    return results


def nuget_available() -> bool:
    # nuget.exe or nuget on PATH
    return shutil.which("nuget") is not None


def dotnet_available() -> bool:
    return shutil.which("dotnet") is not None


def update_package_in_project(csproj: Path, package_id: str, version: str) -> None:
    print(f"[INFO] Updating {package_id} to {version} in {csproj}")
    attempted = False

    if nuget_available():
        # nuget update works best for packages.config managed projects.
        # Still attempt it; if it fails, fall back to dotnet add package.
        attempted = True
        ok = safe_run(
            ["nuget", "update", str(csproj), "-Id", package_id, "-Version", version, "-NonInteractive"],
            cwd=csproj.parent,
        )
        if ok:
            print(f"[INFO] nuget update succeeded for {csproj} ({package_id} -> {version})")
            return
        else:
            print(f"[WARN] nuget update did not succeed for {csproj}; will try dotnet add package if available.")

    if dotnet_available():
        attempted = True
        ok = safe_run(["dotnet", "add", str(csproj), "package", package_id, "--version", version], cwd=csproj.parent)
        if ok:
            print(f"[INFO] dotnet add package succeeded for {csproj} ({package_id} -> {version})")
            return
        else:
            print(f"[ERROR] dotnet add package failed for {csproj} ({package_id})")

    if not attempted:
        print("[ERROR] Neither nuget.exe nor dotnet CLI found on PATH; cannot update packages.")


def run_tests(repo_dir: Path) -> None:
    sln = find_solution(repo_dir)
    if sln and dotnet_available():
        run(["dotnet", "test", str(sln), "--nologo"], cwd=repo_dir)
    elif dotnet_available():
        run(["dotnet", "test", "--nologo"], cwd=repo_dir)
    else:
        print("[ERROR] dotnet CLI not found; cannot run tests.")


def modify_mvc_builder_extensions(repo_dir: Path) -> int:
    files = find_cs_files(repo_dir, "MvcBuilderExtensions.cs")
    changes = 0
    for f in files:
        if insert_timezone_after_target_line(f):
            changes += 1
    print(f"[INFO] Modified {changes} file(s) in repository {repo_dir.name}")
    return changes


def process_repository(repo_root: Path, folder_name: str) -> None:
    repo_dir = repo_root / folder_name
    if not repo_dir.exists():
        print(f"[WARN] Folder not found: {repo_dir}. Skipping.")
        return
    if not is_git_repo(repo_dir):
        print(f"[WARN] Not a git repository: {repo_dir}. Skipping.")
        return

    with pushd(repo_dir):
        print(f"[INFO] Processing repository: {repo_dir}")

        # Ensure clean main from origin and then feature branch
        ensure_on_main_at_origin(repo_dir)
        ensure_feature_branch_from_origin_main(repo_dir)

        # Code modification (replace single line with two lines by inserting new one after target)
        modify_mvc_builder_extensions(repo_dir)

        # NuGet updates
        main_csproj = find_main_project_csproj(repo_dir, folder_name)
        if main_csproj:
            update_package_in_project(main_csproj, API_PACKAGE[0], API_PACKAGE[1])
        else:
            print(f"[WARN] Main project .csproj not found for '{folder_name}' under {repo_dir}/src")

        storage_projects = find_storage_csprojs(repo_dir)
        if not storage_projects:
            print(f"[INFO] No *.Storage.csproj projects found under {repo_dir}/src")
        for csproj in storage_projects:
            update_package_in_project(csproj, STORAGE_PACKAGE[0], STORAGE_PACKAGE[1])

        # Run tests
        run_tests(repo_dir)

        print(f"[INFO] Completed repository: {repo_dir}")


def main():
    start_dir = Path.cwd()
    print(f"[INFO] Starting in: {start_dir}")

    try:
        for folder in FOLDERS:
            process_repository(start_dir, folder)
    finally:
        # Ensure we return to where we started, even if errors occurred
        os.chdir(start_dir)
        print(f"[INFO] Returned to starting directory: {Path.cwd()}")


if __name__ == "__main__":
    main()
