Below is a commented Python implementation that computes:
- the (row, col) minor (determinant of the matrix with that row and column removed),
- the cofactor (signed minor),
- a fast path for 2×2 minors.

It uses a determinant routine based on Gaussian elimination with partial pivoting for O(n^3) time, which is far more efficient and numerically stable than recursive Laplace expansion.

```python
from typing import List

Matrix = List[List[float]]

def submatrix(A: Matrix, row: int, col: int) -> Matrix:
    """
    Return the (n-1)×(n-1) submatrix of A by removing 'row' and 'col'.

    Complexity:
    - Time: O(n^2) (we copy all remaining entries)
    - Space: O(n^2) (new matrix of size (n-1)×(n-1))
    """
    n = len(A)
    if any(len(r) != n for r in A):
        raise ValueError("Matrix must be square.")
    if not (0 <= row < n and 0 <= col < n):
        raise IndexError("row/col out of range.")
    return [
        [A[i][j] for j in range(n) if j != col]
        for i in range(n) if i != row
    ]

def det(A: Matrix, eps: float = 1e-15) -> float:
    """
    Determinant via Gaussian elimination with partial pivoting.

    Algorithm:
    - Perform LU-like elimination with row swaps (partial pivoting)
    - Track sign changes due to swaps
    - Multiply diagonal elements of the resulting upper-triangular matrix

    Notes:
    - Partial pivoting improves numerical stability substantially over naive elimination.
    - For singular (or near-singular) matrices, we return 0.0 if the pivot magnitude
      falls below 'eps'.

    Complexity:
    - Time: O(n^3)
    - Space: O(n^2) to store a copy (in-place within the copy)

    Special cases:
    - 0×0 matrix has determinant 1.0 by convention.
    - Optimized 2×2 branch for speed.
    """
    n = len(A)
    if n == 0:
        return 1.0
    if any(len(row) != n for row in A):
        raise ValueError("Matrix must be square.")
    if n == 1:
        return A[0][0]
    if n == 2:
        return A[0][0] * A[1][1] - A[0][1] * A[1][0]

    # Work on a copy so we don't mutate input
    M = [row[:] for row in A]
    sign = 1.0

    for k in range(n):
        # Find pivot row with the largest absolute value in column k
        pivot_row = max(range(k, n), key=lambda i: abs(M[i][k]))
        if abs(M[pivot_row][k]) < eps:
            return 0.0  # Singular (within tolerance)
        # Swap rows if necessary; each swap flips the determinant sign
        if pivot_row != k:
            M[k], M[pivot_row] = M[pivot_row], M[k]
            sign *= -1.0

        pivot = M[k][k]
        # Eliminate entries below the pivot
        for i in range(k + 1, n):
            factor = M[i][k] / pivot
            # Subtract factor * pivot-row from row i
            for j in range(k, n):
                M[i][j] -= factor * M[k][j]

    # Determinant is product of diagonal times the swap sign
    d = sign
    for i in range(n):
        d *= M[i][i]
    return d

def matrix_minor(A: Matrix, row: int, col: int) -> float:
    """
    Minor of A at (row, col): det of the submatrix with that row and column removed.

    Complexity:
    - Construct submatrix: O(n^2)
    - Determinant (Gaussian elimination): O(n^3)
    Overall: O(n^3) time and O(n^2) space.
    """
    return det(submatrix(A, row, col))

def matrix_cofactor(A: Matrix, row: int, col: int) -> float:
    """
    Cofactor at (row, col): (-1)^(row+col) times the minor.
    """
    return ((-1) ** (row + col)) * matrix_minor(A, row, col)

def minor_2x2(A: Matrix, row: int, col: int) -> float:
    """
    Fast path for 2x2 matrices: the minor is the remaining element.

    For A = [[a, b],
             [c, d]]:
    - minor(0,0) = d
    - minor(0,1) = c
    - minor(1,0) = b
    - minor(1,1) = a

    Complexity: O(1)
    """
    if len(A) != 2 or any(len(r) != 2 for r in A):
        raise ValueError("minor_2x2 expects a 2x2 matrix.")
    if row not in (0, 1) or col not in (0, 1):
        raise IndexError("row and col must be 0 or 1 for 2x2.")
    other_row = 1 - row
    other_col = 1 - col
    return A[other_row][other_col]
```

Efficiency and practical notes:
- For general n×n, computing one minor via submatrix + Gaussian elimination is O(n^3). This is efficient and stable enough for moderate n (tens to a few hundreds depending on environment).
- Avoid Laplace expansion (recursive cofactor expansion) for determinants; it is exponential time and becomes intractable quickly.
- If you need many different minors of the same matrix, repeatedly forming submatrices and recomputing determinants will be expensive. There isn’t a simple reuse of a single LU to get all minors, but for:
  - principal minors (removing the same indices for row and col), factorizations like LDL^T/Cholesky (for SPD matrices) or Schur complements can help compute families of minors more efficiently.
  - exact arithmetic on integers, consider using rational/BigInt types (Python handles big ints natively; in C++ you’d need a library).

C++ version (double precision, partial pivoting, and the same API: submatrix, det, minor, cofactor, minor_2x2):

```cpp
#include <vector>
#include <stdexcept>
#include <cmath>
#include <algorithm>

using Matrix = std::vector<std::vector<double>>;

static inline void ensure_square(const Matrix& A) {
    const std::size_t n = A.size();
    for (const auto& row : A) {
        if (row.size() != n) {
            throw std::invalid_argument("Matrix must be square.");
        }
    }
}

Matrix submatrix(const Matrix& A, std::size_t row, std::size_t col) {
    ensure_square(A);
    const std::size_t n = A.size();
    if (row >= n || col >= n) {
        throw std::out_of_range("row/col out of range.");
    }
    Matrix B;
    B.reserve(n > 0 ? n - 1 : 0);
    for (std::size_t i = 0; i < n; ++i) {
        if (i == row) continue;
        std::vector<double> new_row;
        new_row.reserve(n > 0 ? n - 1 : 0);
        for (std::size_t j = 0; j < n; ++j) {
            if (j == col) continue;
            new_row.push_back(A.at(i).at(j));
        }
        B.push_back(std::move(new_row));
    }
    return B;
}

double det(const Matrix& A, double eps = 1e-15) {
    const std::size_t n = A.size();
    if (n == 0) return 1.0;
    ensure_square(A);
    if (n == 1) return A[0][0];
    if (n == 2) return A[0][0] * A[1][1] - A[0][1] * A[1][0];

    // Work on a copy so we don't mutate input
    Matrix M = A;
    double sign = 1.0;

    for (std::size_t k = 0; k < n; ++k) {
        // Find pivot row with largest absolute value in column k
        std::size_t pivot_row = k;
        double max_abs = std::abs(M[k][k]);
        for (std::size_t i = k + 1; i < n; ++i) {
            double val = std::abs(M[i][k]);
            if (val > max_abs) {
                max_abs = val;
                pivot_row = i;
            }
        }
        if (max_abs < eps) {
            return 0.0; // Singular (within tolerance)
        }
        // Swap rows if needed; update sign
        if (pivot_row != k) {
            std::swap(M[k], M[pivot_row]);
            sign *= -1.0;
        }
        const double pivot = M[k][k];
        // Eliminate below pivot
        for (std::size_t i = k + 1; i < n; ++i) {
            double factor = M[i][k] / pivot;
            for (std::size_t j = k; j < n; ++j) {
                M[i][j] -= factor * M[k][j];
            }
        }
    }
    double d = sign;
    for (std::size_t i = 0; i < n; ++i) {
        d *= M[i][i];
    }
    return d;
}

double matrix_minor(const Matrix& A, std::size_t row, std::size_t col) {
    return det(submatrix(A, row, col));
}

double matrix_cofactor(const Matrix& A, std::size_t row, std::size_t col) {
    const bool sign = ((row + col) % 2 == 0);
    return (sign ? 1.0 : -1.0) * matrix_minor(A, row, col);
}

double minor_2x2(const Matrix& A, std::size_t row, std::size_t col) {
    if (A.size() != 2 || A[0].size() != 2 || A[1].size() != 2) {
        throw std::invalid_argument("minor_2x2 expects a 2x2 matrix.");
    }
    if (row > 1 || col > 1) {
        throw std::out_of_range("row and col must be 0 or 1 for 2x2.");
    }
    std::size_t other_row = 1 - row;
    std::size_t other_col = 1 - col;
    return A[other_row][other_col];
}
```

C++ notes:
- det uses Gaussian elimination with partial pivoting (O(n^3)) and returns 0.0 for near-singular matrices using a small epsilon.
- For performance, prefer contiguous storage (e.g., a flat vector) when n is large, but for clarity vector<vector<double>> is fine.
- If you need exact integer results, consider a big-integer/rational library or modular arithmetic (beyond the scope here).

Reminder regarding the original two snippets:
- minor1 is correct only for 2×2 matrices; it’s equivalent to minor_2x2 above.
- minor2 is incorrect; it performs an unrelated sum of 2×2 determinants across indices.

