const fs = require('fs');
const { randomUUID } = require('crypto');
const Papa = require('papaparse');

/**
 * In-memory job registry for tracking long-running imports.
 * For production, back this with Redis/DB if you need durability across restarts.
 */
const JobRegistry = (() => {
  const _jobs = new Map();
  return {
    create(initial = {}) {
      const id = randomUUID();
      const job = {
        id,
        status: 'queued', // queued | running | completed | failed | cancelled
        startedAt: null,
        finishedAt: null,
        processed: 0,
        succeeded: 0,
        failed: 0,
        batches: 0,
        errors: [],
        meta: {},
        ...initial
      };
      _jobs.set(id, job);
      return job;
    },
    get(id) {
      return _jobs.get(id);
    },
    update(id, patch) {
      const job = _jobs.get(id);
      if (!job) return;
      Object.assign(job, patch);
      return job;
    },
    all() {
      return Array.from(_jobs.values());
    }
  };
})();

/**
 * Simple semaphore to limit concurrency of async batch writers.
 */
class Semaphore {
  constructor(max) {
    this.max = max;
    this.count = max;
    this.queue = [];
  }
  acquire() {
    if (this.count > 0) {
      this.count -= 1;
      return Promise.resolve();
    }
    return new Promise((resolve) => this.queue.push(resolve));
  }
  release() {
    if (this.queue.length > 0) {
      const resolve = this.queue.shift();
      resolve();
    } else {
      this.count = Math.min(this.count + 1, this.max);
    }
  }
}

