    condition: Optional[SQLExpr] = None  # Required except for CROSS

@dataclass
class SelectStmt:
    select_list: List[SelectItem]
    from_items: List[FromItem]  # one or more FromItem (tables or join trees)
    where: Optional[SQLExpr] = None


# ============================================================
# Relational Algebra AST (logical plan)
# ============================================================

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RAJoin(RAExpr):
    join_type: str  # 'INNER', 'LEFT', 'RIGHT', 'FULL', 'CROSS'
    left: RAExpr
    right: RAExpr
    condition: Optional[SQLExpr] = None  # None only for CROSS

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]
    child: RAExpr


# ============================================================
# Pretty printing helpers
# ============================================================

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RAJoin):
        on = f", on={expr_to_str(ra.condition)}" if ra.condition is not None else ""
        return f"{pad}Join[type={ra.join_type}{on}]\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


# ============================================================
# Exceptions (basic error handling)
# ============================================================

class TranslationError(Exception):
    pass

class EmptyFromError(TranslationError):
    pass

class EmptySelectListError(TranslationError):
    pass

class DuplicateAliasError(TranslationError):
    pass

class UnknownTableError(TranslationError):
    pass

class MissingJoinConditionError(TranslationError):
    pass

class UnsupportedFeatureError(TranslationError):
    pass


# ============================================================
# Validation helpers (aliases, table existence)
# ============================================================

def collect_aliases(items: List[FromItem]) -> List[str]:
    aliases: List[str] = []
    def walk(fi: FromItem):
        if isinstance(fi, TableRef):
            aliases.append(fi.alias if fi.alias else fi.name)
        elif isinstance(fi, JoinRef):
            walk(fi.left)
            walk(fi.right)
        else:
            raise UnsupportedFeatureError(f"Unknown FromItem: {type(fi).__name__}")
    for it in items:
        walk(it)
    return aliases

def collect_table_names(items: List[FromItem]) -> List[str]:
    names: List[str] = []
    def walk(fi: FromItem):
        if isinstance(fi, TableRef):
            names.append(fi.name)
        elif isinstance(fi, JoinRef):
            walk(fi.left)
            walk(fi.right)
        else:
            raise UnsupportedFeatureError(f"Unknown FromItem: {type(fi).__name__}")
    for it in items:
        walk(it)
    return names

def validate_alias_uniqueness(items: List[FromItem]) -> None:
    seen: Set[str] = set()
    for alias in collect_aliases(items):
        if alias in seen:
            raise DuplicateAliasError(f"Duplicate table alias/name in FROM: '{alias}'")
        seen.add(alias)

def check_tables_exist(items: List[FromItem], catalog: Optional[Dict[str, Set[str]]]) -> None:
    if not catalog:
        return
    for name in collect_table_names(items):
        if name not in catalog:
            raise UnknownTableError(f"Unknown table '{name}'")


# ============================================================
# Lowering FROM items and main translator
# ============================================================

def lower_from_item(fi: FromItem) -> RAExpr:
    if isinstance(fi, TableRef):
        return RATable(fi.name, alias=fi.alias)

    if isinstance(fi, JoinRef):
        jt = fi.join_type.upper()
        if jt not in ("INNER", "LEFT", "RIGHT", "FULL", "CROSS"):
            raise UnsupportedFeatureError(f"Unsupported join type: {fi.join_type}")
        if jt == "CROSS":
            if fi.condition is not None:
                raise UnsupportedFeatureError("CROSS JOIN must not have an ON condition in this toy model.")
        else:
            if fi.condition is None:
                raise MissingJoinConditionError(f"{jt} JOIN requires an ON condition in this toy model.")
        left = lower_from_item(fi.left)
        right = lower_from_item(fi.right)
        return RAJoin(join_type=jt, left=left, right=right, condition=fi.condition)

    raise UnsupportedFeatureError(f"Unknown FromItem: {type(fi).__name__}")

def fold_product(from_items: List[FromItem]) -> RAExpr:
    """
    Build a left-deep product across a list of lowered from-items.
    Each item can already be a join tree (RAJoin) or a simple RATable.
    """
    assert len(from_items) >= 1
    ra: RAExpr = lower_from_item(from_items[0])
    for it in from_items[1:]:
        ra = RAProduct(left=ra, right=lower_from_item(it))
    return ra

def translate_select(stmt: SelectStmt, catalog: Optional[Dict[str, Set[str]]] = None) -> RAExpr:
    # Basic validation
    if not stmt.select_list:
        raise EmptySelectListError("Empty SELECT list is not allowed.")
    if not stmt.from_items:
        raise EmptyFromError("Missing FROM clause.")

    # FROM validations
    validate_alias_uniqueness(stmt.from_items)
    check_tables_exist(stmt.from_items, catalog)

    # Lower FROM to RA tree
    if len(stmt.from_items) == 1:
        ra = lower_from_item(stmt.from_items[0])
    else:
        # Comma in FROM => cross-products between items (which can be join trees themselves)
        ra = fold_product(stmt.from_items)

    # WHERE -> selection
    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    # SELECT list -> projection (omit if SELECT *)
    only_star = len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    if only_star:
        return ra
    return RAProjection(items=stmt.select_list, child=ra)


