```python
# src/lookup/lookup.controller.ts
import { Controller, Get, Post, Query, Res, Req, HttpException, HttpStatus } from '@nestjs/common';
import { readFile } from 'node:fs/promises';
import { buildStoreFromXml, lookup, InMemoryStore } from './indexer';

let STORE: InMemoryStore | null = null;
let RELOADING = false;

async function loadOrReload(): Promise<void> {
  const xmlPath = process.env.XML_PATH || '/app/data/records.xml';
  const recordPath = process.env.XML_RECORD_PATH || 'records.record';
  const primary = process.env.PRIMARY_KEY_FIELD || 'id';
  const fields = (process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean);
  const xml = await readFile(xmlPath, 'utf-8');
  const next = await buildStoreFromXml(xml, { primaryKey: primary, indexFields: fields, recordPath });
  STORE = next; // atomic swap
}

@Controller('lookup')
export class LookupController {
  constructor() {
    // fire and forget at first request time if not eager-loaded in module init
    if (!STORE) loadOrReload().catch(err => console.error('Initial load failed:', err));
  }

  @Get()
  async get(@Query('field') field: string, @Query('value') value: string) {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    if (!field || value == null) throw new HttpException('field and value are required', HttpStatus.BAD_REQUEST);
    return lookup(STORE, field, value);
  }

  @Get('count')
  count() {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    return { count: STORE.records.length };
  }

  @Post('reload')
  async reload(@Req() req) {
    const token = req.headers['x-admin-token'];
    if (token !== (process.env.RELOAD_TOKEN || 'change-me')) {
      throw new HttpException('Forbidden', HttpStatus.FORBIDDEN);
    }
    if (RELOADING) return { status: 'already_reloading' };
    RELOADING = true;
    try {
      await loadOrReload();
      return { status: 'ok' };
    } finally {
      RELOADING = false;
    }
  }

  @Get('fields')
  fields() {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    return { fields: Object.keys(STORE.indexes) };
  }
}
