    strict: false,        // allow any fields initially
    minimize: false,      // keep empty objects if present
    versionKey: false
  }
);

// Example index creation at startup (tune to your fields)
export function ensureMongoIndexes(model) {
  const indexFields = (process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean);
  for (const f of indexFields) {
    model.collection.createIndex({ [f]: 1 }, { name: `idx_${f}` }).catch(console.error);
  }
  const pk = process.env.PRIMARY_KEY_FIELD || 'id';
  model.collection.createIndex({ [pk]: 1 }, { unique: false, name: `idx_${pk}` }).catch(console.error);
}
