# src/lookup/inmemory.repository.ts
import { readFile } from 'node:fs/promises';
import { XMLParser } from 'fast-xml-parser';
import { LookupRepository } from './lookup.repository';

type IndexMap = Map<string, any[]>;
type FieldIndex = Record<string, IndexMap>;

const normalize = (v: any) =>
  typeof v === 'string' ? v.normalize('NFC').trim().toLowerCase() : String(v);

const getByPath = (obj: any, path: string) =>
  path.split('.').reduce((a, k) => (a ? a[k] : undefined), obj);

export class InMemoryRepository implements LookupRepository {
  private records: any[] = [];
  private indexes: FieldIndex = {};

  static async fromXml(): Promise<InMemoryRepository> {
    const repo = new InMemoryRepository();
    const xmlPath = process.env.XML_PATH || '/app/data/records.xml';
    const recordPath = process.env.XML_RECORD_PATH || 'records.record';
    const primary = process.env.PRIMARY_KEY_FIELD || 'id';
    const fields = Array.from(
      new Set([primary, ...(process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean)])
    );

    const xml = await readFile(xmlPath, 'utf-8');
    const parser = new XMLParser({ ignoreAttributes: false, trimValues: true });
    const parsed = parser.parse(xml);
    const arr = getByPath(parsed, recordPath);
    if (!Array.isArray(arr)) throw new Error(`XML_RECORD_PATH not an array: ${recordPath}`);

    repo.records = arr;
    for (const f of fields) repo.indexes[f] = new Map();

    for (const r of repo.records) {
      for (const f of fields) {
        const raw = r[f];
        if (raw == null) continue;
        const key = normalize(raw);
        const list = repo.indexes[f].get(key);
        if (list) list.push(r); else repo.indexes[f].set(key, [r]);
      }
    }
    return repo;
  }

  async find(field: string, value: string): Promise<any[]> {
    const idx = this.indexes[field];
    if (!idx) return [];
    return idx.get(normalize(value)) || [];
  }
  async count(): Promise<number> { return this.records.length; }
  fields(): string[] { return Object.keys(this.indexes); }
}
