const fs = require('fs');
const fsp = require('fs/promises');
const path = require('path');
const sharp = require('sharp');

/**
 * List watermark files from a directory or accept a single file or array of files.
 * Accepts .png and .webp by default (alpha-friendly). You can extend if needed.
 */
async function resolveWatermarkSources(watermarkSources) {
  if (Array.isArray(watermarkSources)) {
    return watermarkSources;
  }
  const p = String(watermarkSources);
  try {
    const st = await fsp.stat(p);
    if (st.isDirectory()) {
      const files = await fsp.readdir(p);
      return files
        .map(fn => path.join(p, fn))
        .filter(fp => /\.(png|webp)$/i.test(fp));
    }
    return [p];
  } catch {
    // Treat as a single path (may fail later if it doesn't exist)
    return [p];
  }
}

/**
