from __future__ import annotations
import os, gzip
from collections import defaultdict
from typing import Dict, Set, Tuple

def _open_any(path: str):
    return gzip.open(path, "rt") if path.endswith(".gz") else open(path, "r")

def _strip_type_prefix(val: str) -> str:
    # Remove typed prefixes like gene:, transcript:, mRNA:, exon:
    if ":" in val:
        return val.split(":", 1)[1]
    return val

def _parse_attrs(attr: str) -> Dict[str, str]:
    out: Dict[str, str] = {}
    for part in attr.strip().split(";"):
        part = part.strip()
        if not part or "=" not in part:
            continue
        k, v = part.split("=", 1)
        out[k] = v
    return out

def diagnose_gff3(path: str, sample_lines: int = 5000) -> None:
    print(f"Path: {path}")
    if not os.path.isfile(path):
        print("ERROR: File does not exist or is not a regular file.")
        return
    print("File exists. Checking format hints ...")
    has_gff_header = False
    gff_attr_hits = 0
    gtf_attr_hits = 0
    features: Dict[str, int] = defaultdict(int)
    with _open_any(path) as fh:
        for i, line in enumerate(fh, 1):
            if i > sample_lines:
                break
            if line.startswith("##gff-version"):
                has_gff_header = True
            if line.startswith("#") or not line.strip():
                continue
            cols = line.rstrip("\n").split("\t")
            if len(cols) < 9:
                continue
            ftype, attrs = cols[2], cols[8]
            features[ftype] += 1
            if "ID=" in attrs or "Parent=" in attrs:
                gff_attr_hits += 1
            if 'gene_id "' in attrs or 'transcript_id "' in attrs:
                gtf_attr_hits += 1
    print(f"Header says GFF3: {has_gff_header}")
    print(f"GFF3-style attrs (ID=/Parent=) hits: {gff_attr_hits}")
    print(f"GTF-style attrs (gene_id/transcript_id) hits: {gtf_attr_hits}")
    print("Top features:")
    for k, v in sorted(features.items(), key=lambda kv: kv[1], reverse=True)[:10]:
        print(f"  {k}: {v}")

def count_exons_per_gene(gff3_path: str, unique_per_gene: bool = False) -> Dict[str, int]:
    """
    Two-pass count of exons per gene from a GFF3 file.
    - Pass 1: build transcript -> gene map from transcript/mRNA features (ID and Parent).
    - Pass 2: for each exon, resolve Parent transcript(s) to a gene and increment counts.
    - If unique_per_gene=True, deduplicate by (seqid, strand, start, end) per gene.
    """
    t2g: Dict[str, str] = {}
    with _open_any(gff3_path) as fh:
        for line in fh:
            if not line or line.startswith("#"):
                continue
            cols = line.rstrip("\n").split("\t")
            if len(cols) < 9:
                continue
            ftype = cols[2]
            if ftype not in ("transcript", "mRNA"):
                continue
            attrs = _parse_attrs(cols[8])
            tid = _strip_type_prefix(attrs.get("ID", "").strip())
            gid = _strip_type_prefix(attrs.get("Parent", "").strip())
            if tid and gid:
                t2g[tid] = gid

    counts: Dict[str, int] = defaultdict(int)
    uniq: Dict[str, Set[Tuple[str, str, int, int]]] = defaultdict(set) if unique_per_gene else {}
    with _open_any(gff3_path) as fh:
        for line in fh:
            if not line or line.startswith("#"):
                continue
            cols = line.rstrip("\n").split("\t")
            if len(cols) < 9:
                continue
            seqid, _, ftype, start, end, _, strand, _, attr = cols
            if ftype != "exon":
                continue
            a = _parse_attrs(attr)
            parents = a.get("Parent", "")
            if not parents:
                continue
            for tid in parents.split(","):
                tid = _strip_type_prefix(tid.strip())
                gid = t2g.get(tid)
                if not gid:
                    continue
                if unique_per_gene:
                    try:
                        s, e = int(start), int(end)
                    except ValueError:
                        continue
                    uniq[gid].add((seqid, strand or ".", s, e))
                else:
                    counts[gid] += 1
    if unique_per_gene:
        return {g: len(coords) for g, coords in uniq.items()}
    return dict(counts)

