// Projects a vector w onto the simplex {y: sum y = 1, minW[i] <= y[i] <= maxW[i]}.
// Uses the optimal projection via bisection on the Lagrange multiplier tau:
// y_i = clip(w_i - tau, minW[i], maxW[i]) s.t. sum_i y_i = 1
func projectToSimplexWithBounds(w []float64, minW, maxW []float64) {
	n := len(w)

	// Quick feasibility check
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0 {
		// Not feasible; set to min (best effort)
		copy(w, minW)
		return
	}
	if sumMax < 1.0 {
		// Not feasible; set to max (best effort)
		copy(w, maxW)
		return
	}

	// Determine bounds for tau such that S(tau) = sum clip(w_i - tau) spans 1
	tauLow := math.Inf(1)
	tauHigh := math.Inf(-1)
	for i := 0; i < n; i++ {
		low := w[i] - maxW[i] // when tau <= low => y_i = maxW[i]
		high := w[i] - minW[i] // when tau >= high => y_i = minW[i]
		if low < tauLow {
			tauLow = low
		}
		if high > tauHigh {
			tauHigh = high
		}
	}

	// Bisection on tau
	for iter := 0; iter < 60; iter++ {
		tau := 0.5*(tauLow+tauHigh)
		sum := 0.0
		for i := 0; i < n; i++ {
			val := w[i] - tau
			if val < minW[i] {
				val = minW[i]
			}
			if val > maxW[i] {
				val = maxW[i]
			}
			sum += val
		}
		if sum > 1.0 {
			// Need to decrease sum -> increase tau
			tauLow = tau
		} else {
			// Need to increase sum -> decrease tau
			tauHigh = tau
		}
	}
	// Final projection with chosen tau
	tau := 0.5*(tauLow+tauHigh)
	for i := 0; i < n; i++ {
		val := w[i] - tau
		if val < minW[i] {
			val = minW[i]
		}
		if val > maxW[i] {
			val = maxW[i]
		}
		w[i] = val
	}

	// Final normalization safeguard (numeric)
	sum := 0.0
	for i := 0; i < n; i++ {
		sum += w[i]
	}
	if sum != 0 {
		for i := 0; i < n; i++ {
