# lib/pages/profile_details_page.dart
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import 'package:provider/provider.dart';

import '../state/onboarding_state.dart';
import '../services/auth_service.dart';
import '../services/storage_service.dart';
import '../services/user_repository.dart';
import 'profile_page.dart';

class ProfileDetailsPage extends StatefulWidget {
  static const routeName = '/profile_details';
  const ProfileDetailsPage({super.key});

  @override
  State<ProfileDetailsPage> createState() => _ProfileDetailsPageState();
}

class _ProfileDetailsPageState extends State<ProfileDetailsPage> {
  final _formKey = GlobalKey<FormState>();
  final _weightCtrl = TextEditingController();
  final _heightCtrl = TextEditingController();
  final _bodyCtrl = TextEditingController();
  final _picker = ImagePicker();

  File? _photoFile;
  bool _saving = false;

  final _auth = AuthService();
  final _storage = StorageService();
  final _repo = UserRepository();

  @override
  void dispose() {
    _weightCtrl.dispose();
    _heightCtrl.dispose();
    _bodyCtrl.dispose();
    super.dispose();
  }

  Future<void> _pickImage(ImageSource source) async {
    try {
      final picked = await _picker.pickImage(source: source, imageQuality: 85);
      if (picked != null) {
        setState(() {
          _photoFile = File(picked.path);
        });
        context.read<OnboardingState>().setPhoto(_photoFile);
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to pick image: $e')),
      );
    }
  }

  String? _validateNumber(String? v, String field) {
    if (v == null || v.trim().isEmpty) return '$field is required';
    final parsed = double.tryParse(v.trim());
    if (parsed == null || parsed <= 0) return 'Enter a valid $field';
    return null;
  }

  Future<void> _save() async {
    final onboarding = context.read<OnboardingState>();
    if (onboarding.firstName == null || onboarding.lastName == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Missing name from the previous step')),
      );
      Navigator.pop(context);
      return;
    }

    if (!_formKey.currentState!.validate()) return;

    final user = _auth.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('No authenticated user. Please sign up again.')),
      );
      Navigator.popUntil(context, ModalRoute.withName('/email'));
      return;
    }

    setState(() => _saving = true);

    try {
      final double weight = double.parse(_weightCtrl.text.trim());
      final double height = double.parse(_heightCtrl.text.trim());
      final String bodyType = _bodyCtrl.text.trim();

      // Update local state
      onboarding.setMetrics(weightKg: weight, heightCm: height, body: bodyType);

      // Upload profile photo if selected
      String? photoUrl;
      if (_photoFile != null) {
        photoUrl = await _storage.uploadUserProfilePhoto(uid: user.uid, file: _photoFile!);
      }

      // Update Firebase Auth user profile (displayName and photoURL)
      final displayName = '${onboarding.firstName!} ${onboarding.lastName!}'.trim();
      await _auth.updateProfile(displayName: displayName, photoURL: photoUrl);

      // Save to Firestore
      await _repo.saveUserProfile(
        uid: user.uid,
        email: onboarding.email ?? user.email ?? '',
        firstName: onboarding.firstName!,
        lastName: onboarding.lastName!,
        weight: weight,
        height: height,
        bodyType: bodyType,
        photoUrl: photoUrl,
      );

      if (!mounted) return;
      // Navigate to Profile Page
      Navigator.pushNamedAndRemoveUntil(context, ProfilePage.routeName, (route) => false);
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to save profile: $e')),
      );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final onboarding = context.watch<OnboardingState>();
    final namePreview =
        '${onboarding.firstName ?? ''} ${onboarding.lastName ?? ''}'.trim();

    return Scaffold(
      appBar: AppBar(title: const Text('Profile Details')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            // Photo picker
            Center(
              child: Stack(
                children: [
                  CircleAvatar(
                    radius: 56,
                    backgroundColor: Colors.grey.shade300,
                    backgroundImage:
                        _photoFile != null ? FileImage(_photoFile!) : null,
                    child: _photoFile == null
                        ? Text(
                            namePreview.isNotEmpty
                                ? namePreview
                                    .split(' ')
                                    .where((s) => s.isNotEmpty)
                                    .map((s) => s[0].toUpperCase())
                                    .take(2)
                                    .join()
                                : 'P',
                            style: const TextStyle(
                              fontSize: 28,
                              color: Colors.white,
                            ),
                          )
                        : null,
                  ),
                  Positioned(
                    bottom: -6,
                    right: -6,
                    child: Row(
                      children: [
                        IconButton(
                          icon: const Icon(Icons.photo, color: Colors.blue),
                          onPressed: () => _pickImage(ImageSource.gallery),
                          tooltip: 'Pick from gallery',
                        ),
                        IconButton(
                          icon: const Icon(Icons.photo_camera, color: Colors.blue),
                          onPressed: () => _pickImage(ImageSource.camera),
                          tooltip: 'Take a photo',
                        ),
                      ],
                    ),
                  )
                ],
              ),
            ),
            const SizedBox(height: 24),
            Form(
              key: _formKey,
              child: Column(
                children: [
                  TextFormField(
                    controller: _weightCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Weight (kg)',
                      hintText: 'e.g. 70',
                    ),
                    keyboardType: TextInputType.numberWithOptions(decimal: true),
                    validator: (v) => _validateNumber(v, 'weight'),
                  ),
                  const SizedBox(height: 12),
                  TextFormField(
                    controller: _heightCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Height (cm)',
                      hintText: 'e.g. 175',
                    ),
                    keyboardType: TextInputType.numberWithOptions(decimal: true),
                    validator: (v) => _validateNumber(v, 'height'),
                  ),
                  const SizedBox(height: 12),
                  TextFormField(
                    controller: _bodyCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Body Type',
                      hintText: 'e.g. Athletic',
                    ),
                    validator: (v) {
                      if (v == null || v.trim().isEmpty) return 'Body type is required';
                      return null;
                    },
                  ),
                ],
              ),
            ),
            const SizedBox(height: 24),
            _saving
                ? const CircularProgressIndicator()
                : SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      onPressed: _save,
                      icon: const Icon(Icons.check),
                      label: const Text('Save and Continue'),
                    ),
                  ),
          ],
        ),
      ),
    );
  }
}
