# lib/pages/profile_page.dart
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';

import '../services/auth_service.dart';
import '../services/user_repository.dart';
import 'email_page.dart';

class ProfilePage extends StatelessWidget {
  static const routeName = '/profile';
  const ProfilePage({super.key});

  @override
  Widget build(BuildContext context) {
    final auth = AuthService();
    final repo = UserRepository();

    final user = auth.currentUser;
    if (user == null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Profile')),
        body: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Text('No user signed in.'),
              const SizedBox(height: 12),
              ElevatedButton(
                onPressed: () {
                  Navigator.pushNamedAndRemoveUntil(
                    context,
                    EmailPage.routeName,
                    (route) => false,
                  );
                },
                child: const Text('Start Sign Up'),
              )
            ],
          ),
        ),
      );
    }

    return Scaffold(
      appBar: AppBar(title: const Text('Your Profile')),
      body: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: repo.streamUser(user.uid),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          if (snapshot.hasError) {
            return Center(
              child: Text('Error loading profile: ${snapshot.error}'),
            );
          }
          final data = snapshot.data?.data() ?? {};

          final photoUrl = data['photoUrl'] as String?;
          final firstName = data['firstName'] as String? ?? '';
          final lastName = data['lastName'] as String? ?? '';
          final email = data['email'] as String? ?? user.email ?? '';
          final weight = (data['weight'] as num?)?.toDouble();
          final height = (data['height'] as num?)?.toDouble();
          final bodyType = data['bodyType'] as String? ?? '';

          final displayName = '$firstName $lastName'.trim();

          return SingleChildScrollView(
            padding: const EdgeInsets.all(16),
            child: Column(
              children: [
                CircleAvatar(
                  radius: 56,
                  backgroundColor: Colors.grey.shade300,
                  backgroundImage: (photoUrl != null && photoUrl.isNotEmpty)
                      ? NetworkImage(photoUrl)
                      : null,
                  child: (photoUrl == null || photoUrl.isEmpty)
                      ? Text(
                          displayName.isNotEmpty
                              ? displayName
                                  .split(' ')
                                  .where((s) => s.isNotEmpty)
                                  .map((s) => s[0].toUpperCase())
                                  .take(2)
                                  .join()
                              : 'U',
                          style: const TextStyle(fontSize: 28, color: Colors.white),
                        )
                      : null,
                ),
                const SizedBox(height: 16),
                Text(
                  displayName.isEmpty ? 'Unnamed User' : displayName,
                  style: Theme.of(context).textTheme.headlineSmall,
                ),
                const SizedBox(height: 4),
                Text(email, style: Theme.of(context).textTheme.bodyMedium),
                const SizedBox(height: 24),
                Card(
                  child: Padding(
                    padding: const EdgeInsets.all(16),
                    child: Column(
                      children: [
                        _row('Weight', weight != null ? '$weight kg' : '—'),
                        const Divider(),
                        _row('Height', height != null ? '$height cm' : '—'),
                        const Divider(),
                        _row('Body Type', bodyType.isNotEmpty ? bodyType : '—'),
                      ],
                    ),
                  ),
                ),
                const SizedBox(height: 24),
                Text(
                  'This profile is synced from Firestore and your photo is served from Firebase Storage.',
                  textAlign: TextAlign.center,
                  style: Theme.of(context).textTheme.bodySmall?.copyWith(color: Colors.grey[700]),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  Widget _row(String label, String value) {
    return Row(
      children: [
        Expanded(child: Text(label, style: const TextStyle(fontWeight: FontWeight.w600))),
        Text(value),
      ],
    );
  }
}
```

How it works end-to-end:
- After signup and setting name, ProfileDetailsPage lets the user pick a photo and enter weight, height, and body type.
- On Save:
  - Optional photo uploads to Firebase Storage under users/<uid>/profile.jpg and returns a download URL.
  - Firebase Auth profile is updated with displayName and photoURL.
  - Firestore users/<uid> document is written with profile fields.
  - Navigation proceeds to ProfilePage.
- ProfilePage streams users/<uid> from Firestore and displays the photo, name, email, and metrics.

