# lib/state/onboarding_state.dart
import 'package:flutter/material.dart';

class OnboardingState extends ChangeNotifier {
  String? email;
  String? password;
  String? firstName;
  String? lastName;

  void setEmail(String value) {
    email = value.trim();
    notifyListeners();
  }

  void setPassword(String value) {
    password = value;
    notifyListeners();
  }

  void setName(String first, String last) {
    firstName = first.trim();
    lastName = last.trim();
    notifyListeners();
  }

  void reset() {
    email = null;
    password = null;
    firstName = null;
    lastName = null;
    notifyListeners();
  }
}
