class StorageService {
  final FirebaseStorage _storage = FirebaseStorage.instance;

  Future<String?> uploadUserProfilePhoto({
    required String uid,
    required File file,
  }) async {
    final ref = _storage.ref('users/$uid/profile.jpg');
