Below is the completed single-file MATLAB script with finished slip, ABScycle, and tiremodel functions so it runs end-to-end. Save as abs_simulation.m and run in MATLAB (R2016b+ supports local functions at the end of scripts). The ABScycle implements a simple on-off controller with rate-limited pressure changes, slip is guarded and bounded in [0,1] for braking, and tiremodel uses the Burckhardt model.

```python
% ABS braking system simulation (single wheel, quarter-car approximation)
% Mechatronics-oriented implementation with:
% - Braking_torque function
% - ramp function
% - slip function
% - ABScycle function
% - tiremodel function
% - main script

clear; clc; close all;

%% Parameters
% Vehicle and wheel
m_total   = 1500;           % total vehicle mass [kg]
m_q       = m_total/4;      % quarter-vehicle mass [kg]
g         = 9.81;           % gravity [m/s^2]
Fz        = m_q * g;        % normal load per wheel [N]
R         = 0.30;           % wheel effective radius [m]
Iw        = 1.8;            % wheel rotational inertia [kg*m^2]

% Initial conditions
v0        = 30;             % initial vehicle speed [m/s] ~108 km/h
w0        = v0 / R;         % initial wheel angular speed [rad/s]

% Brake actuator and ABS controller
T_brk_max = 1500;           % max brake torque per wheel [N*m]
P_min     = 0.0;            % min brake pressure command (normalized)
P_max     = 1.0;            % max brake pressure command (normalized)
dP_up     = 30;             % pressure increase rate [1/s]
dP_down   = 60;             % pressure decrease rate [1/s]
s_low     = 0.12;           % ABS slip lower threshold
s_high    = 0.20;           % ABS slip upper threshold
v_cutoff  = 0.5;            % below this vehicle speed, disable ABS and pressure [m/s]

% Tire model (Burckhardt coefficients: dry road)
tire.a1 = 1.28;
tire.a2 = 23.99;
tire.a3 = 0.52;

% Simulation settings
dt        = 1e-3;           % time step [s]
t_end     = 10.0;           % maximum simulation time [s]
N         = ceil(t_end/dt)+1;

% Toggle ABS on/off for comparison (1=ABS enabled, 0=full pressure)
ABS_on    = 1;

%% Preallocate arrays
t    = zeros(N,1);
v    = zeros(N,1);    v(1) = v0;
w    = zeros(N,1);    w(1) = w0;
sl   = zeros(N,1);
mu   = zeros(N,1);
Fx   = zeros(N,1);
Tb   = zeros(N,1);
P    = zeros(N,1);    P(1) = 0.0; % start with no pressure, ABS will ramp up

%% Simulation loop
k_stop = N;
for k = 1:N-1
    t(k+1) = t(k) + dt;

    % Compute slip (use current v, w)
    sl(k) = slip(v(k), w(k), R);

    % Tire force from tire model
    mu(k) = tiremodel(sl(k), tire);
    Fx(k) = mu(k) * Fz;                 % longitudinal tire force [N]

    % Control pressure via ABS cycle
    if ABS_on
        if v(k) > v_cutoff
            P(k+1) = ABScycle(sl(k), s_low, s_high, P(k), dt, dP_up, dP_down, P_min, P_max);
        else
            P(k+1) = 0.0; % below cutoff, release brake to prevent standstill chatter
        end
    else
        % No ABS: constant full brake pressure (rate limited ramp-up for realism)
        P(k+1) = ramp(P(k), P_max, dP_up, dP_down, dt, P_min, P_max);
    end

    % Brake torque from current pressure
    Tb(k) = Braking_torque(P(k), T_brk_max);

    % Wheel and vehicle dynamics
    % Iw * w_dot = Tb - Fx * R
    w_dot = (Tb(k) - Fx(k)*R) / Iw;
    v_dot = -Fx(k) / m_q;

    % Integrate (Euler) with non-negative clamps
    w(k+1) = max(0, w(k) + w_dot*dt);
    v(k+1) = max(0, v(k) + v_dot*dt);

    % Stop condition
    if v(k+1) <= 0.05
        k_stop = k+1;
        v(k+1) = 0;
        w(k+1) = 0;
        P(k+1) = 0;
        break;
    end
end

% Trim arrays to actual simulation length
t  = t(1:k_stop);
v  = v(1:k_stop);
w  = w(1:k_stop);
P  = P(1:k_stop);
Tb = Tb(1:k_stop);
sl = sl(1:k_stop);
mu = mu(1:k_stop);
Fx = Fx(1:k_stop);

% Ensure last slip and mu are consistent with final states
sl(end) = slip(v(end), w(end), R);
mu(end) = tiremodel(sl(end), tire);
Fx(end) = mu(end) * Fz;

%% Outputs
disp('Simulation finished.');
distance = trapz(t, v);
fprintf('Stopping time: %.2f s, Distance (approx. via trapezoid): %.1f m\n', t(end), distance);

%% Plots
figure('Name','ABS Simulation','Color','w');

% Speeds
subplot(3,1,1);
plot(t, v, 'b', 'LineWidth',1.5); hold on;
plot(t, w*R, 'r--', 'LineWidth',1.2);
ylabel('Speed [m/s]'); grid on;
