# my_attr/src/lib.rs
use proc_macro::TokenStream;
use quote::quote;
use syn::{self, ItemFn};

/// Attribute macro that accepts:
/// - #[my_attr]                        // no args
/// - #[my_attr(name = "some string")]  // a single named string argument
///
/// Any malformed input is reported via `compile_error!` with spans, not panics.
#[proc_macro_attribute]
pub fn my_attr(attr: TokenStream, item: TokenStream) -> TokenStream {
    // Parse the item: we require a function. Emit compile-time error on failure.
    let func: ItemFn = match syn::parse(item) {
        Ok(f) => f,
        Err(e) => return e.to_compile_error().into(),
    };

    // Parse attribute args using syn v2 meta parser.
    // Accept an optional `name = "..."` argument.
    let mut name_lit: Option<syn::LitStr> = None;

    let parser = syn::meta::parser(|meta: syn::meta::ParseNestedMeta| {
        if meta.path.is_ident("name") {
            // Disallow duplicates.
            if name_lit.is_some() {
                return Err(meta.error("duplicate argument `name`"));
            }
            // Require name = "string"
            let value: syn::LitStr = meta.value()?.parse()?;
            name_lit = Some(value);
            Ok(())
        } else {
            Err(meta.error("unexpected argument; expected `name = \"...\"`"))
        }
    });

    // Fully parse the proc-macro attribute input stream.
    if let Err(e) = parser.parse2(attr.into()) {
        return e.to_compile_error().into();
    }

    // For this minimal example we leave the function unchanged. In a real macro you might
    // use `name_lit` to generate additional code.
    quote!(#func).into()
}
