        Err(e) => return e.to_compile_error().into(),
    };

    // Parse attribute args using syn v2 nested meta parser.
    // Accept an optional `name = "..."` argument.
    let mut name_lit: Option<syn::LitStr> = None;

    let parser = syn::meta::parser(|meta: syn::meta::ParseNestedMeta| {
        if meta.path.is_ident("name") {
            // Disallow duplicates.
            if name_lit.is_some() {
                return Err(meta.error("duplicate argument `name`"));
            }
            // Require name = "string"
            let value: syn::LitStr = meta.value()?.parse()?;
            name_lit = Some(value);
            Ok(())
        } else {
            Err(meta.error("unexpected argument; expected `name = \"...\"`"))
        }
    });

    // Fully parse the proc-macro attribute input stream and report any errors.
    if let Err(e) = parser.parse2(attr.into()) {
        return e.to_compile_error().into();
    }

    // Minimal example: leave the function unchanged.
    // In a real macro, you might use `name_lit` to generate code.
    quote!(#func).into()
}
