# ----------------------------------------
# Engine-agnostic reference: contact-band blend (Python/NumPy)
# ----------------------------------------
import numpy as np

def smoothstep(edge0, edge1, x):
    t = np.clip((x - edge0) / max(edge1 - edge0, 1e-8), 0.0, 1.0)
    return t * t * (3.0 - 2.0 * t)

def blend_contact_band(front_color, front_depth, back_color, back_depth,
                       seam_thickness=0.15, seam_feather=0.30):
    # front_depth/back_depth are linear view-space distances (smaller = closer)
    delta = np.abs(front_depth - back_depth)
    w = 1.0 - smoothstep(seam_thickness, seam_feather, delta)
    w = w[..., None]
    return np.clip(front_color * (1.0 - w) + back_color * w, 0.0, 1.0)

